function validate([nums, k]) {
  if (!Number.isInteger(k) || k < 0 || k > 100000) return 'k is between 0 and 100000.';
  if (nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.length % 2 !== 0) return 'nums must have an even length.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > k)) return 'Each value is between 0 and k.';
  return null;
}

