function minChanges(nums, k) {
  const n = nums.length;
  const diff = new Array(k + 2).fill(0);
  for (let i = 0; i < n / 2; i++) {
    const low = Math.min(nums[i], nums[n - 1 - i]);
    const high = Math.max(nums[i], nums[n - 1 - i]);
    const gap = high - low;
    const reach = Math.max(high, k - low);
    diff[0] += 1;
    diff[gap] -= 1;
    diff[gap + 1] += 1;
    diff[reach + 1] += 1;
  }
  let best = n;
  let changes = 0;
  for (let x = 0; x <= k; x++) {
    changes += diff[x];
    best = Math.min(best, changes);
  }
  return best;
}

