function minChanges(nums, k) {
  const n = nums.length;
  let best = Infinity;
  for (let x = 0; x <= k; x++) {
    let total = 0;
    for (let i = 0; i < n / 2; i++) {
      const a = nums[i], b = nums[n - 1 - i];
      if (Math.abs(a - b) === x) continue;
      // Replace a with b - x or b + x, or b with a - x or a + x, if one of them stays in [0, k].
      const one = [b - x, b + x, a - x, a + x].some(v => v >= 0 && v <= k);
      total += one ? 1 : 2;
    }
    best = Math.min(best, total);
  }
  return best;
}

