function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 * (1 + Math.floor(rand() * 5));
  const k = size === 'large' ? (rand() < 0.5 ? Math.floor(rand() * 100001) : Math.floor(rand() * 60)) : Math.floor(rand() * 9);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (k + 1)));
  // Plant one common gap in some mirrored pairs so the best X is not always trivial.
  const target = Math.floor(rand() * (k + 1));
  for (let i = 0; i < n / 2; i++) {
    if (rand() < 0.4) {
      const low = Math.floor(rand() * (k - target + 1));
      const flip = rand() < 0.5;
      nums[i] = flip ? low : low + target;
      nums[n - 1 - i] = flip ? low + target : low;
    }
  }
  return [nums, k];
}
